#pragma once

#include "common/types.hpp"
#include "deadlock/wait_for_graph.hpp"
#include "deadlock/cycle_detector.hpp"
#include "deadlock/victim_selector.hpp"
#include <string>

namespace oscope {

class DeadlockDetector {
public:
    explicit DeadlockDetector(const std::string& defaultStrategy = "LEAST_COST");

    // Inspects a state file generated by instrumented multithreaded test workloads
    // Format per line in state file:
    // HOLD <thread_id> <resource_name>
    // WAIT <thread_id> <resource_name>
    DeadlockGraph analyzeFromStateFile(const std::string& stateFilePath);

    // Analyzes a pre-populated WaitForGraph
    DeadlockGraph analyzeGraph(WaitForGraph& graph);

    void setStrategy(const std::string& strategy) { strategy_ = strategy; }
    std::string getStrategy() const { return strategy_; }

private:
    std::string strategy_;
    CycleDetector cycleDetector_;
};

} // namespace oscope
